// HasWorkItem applies the HasEdge predicate on the "work_item" edge.
func HasWorkItem() predicate.IntakeRequest {
	return predicate.IntakeRequest(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, false, WorkItemTable, WorkItemColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasWorkItemWith applies the HasEdge predicate on the "work_item" edge with a given conditions (other predicates).
func HasWorkItemWith(preds ...predicate.Ticket) predicate.IntakeRequest {
	return predicate.IntakeRequest(func(s *sql.Selector) {
		step := newWorkItemStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.IntakeRequest) predicate.IntakeRequest {
	return predicate.IntakeRequest(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.IntakeRequest) predicate.IntakeRequest {
	return predicate.IntakeRequest(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.IntakeRequest) predicate.IntakeRequest {
	return predicate.IntakeRequest(sql.NotPredicates(p))
}
